'use strict';
window.ShelterEngine=(()=>{
 const VERSION=2,MAX_OFFLINE=8*3600000,MAX_FLOORS=30;
 const FIRST=['林','陈','许','周','沈','方','苏','陆','顾','宋','夏','温','何','程','白','徐'],LAST=['小雨','木','星','岚','知','晴','禾','野','川','安','叶','竹','穗','一','露','宁'];
 const randint=n=>Math.floor(Math.random()*n);
 function person(id){return {id,name:FIRST[randint(16)]+LAST[randint(16)],age:18+randint(48),specialty:Object.keys(SPECIALTIES)[randint(5)],floor:null,look:{head:randint(16),top:randint(16),bottom:randint(16)}};}
 function floor(type,index,now,paid=false){const t=ROOMS[type];return {id:index+1,type,name:t.name,level:index+1,capacity:t.capacity,buildCost:paid?t.cost:0,buildSeconds:paid?t.seconds:0,startedAt:now,readyAt:now+(paid?t.seconds*1000:0),enabled:true,income:t.income,expense:t.expense};}
 function fresh(now=Date.now()){const p=[1,2,3,4].map(person);p[0].name='林小雨';p[0].specialty='growth';p[0].floor=2;p[1].name='陈木';p[1].specialty='culture';p[1].floor=3;return {version:VERSION,coins:1000,floors:[floor('dorm',0,now),floor('cultivation',1,now),floor('library',2,now)],people:p,visitors:[{...person(5),destination:2}],nextId:6,nextVisitorAt:now+45000,createdAt:now,lastTick:now,earned:0,transported:0,claimed:[],logs:[{at:now,text:'07 号避难所重新开放。欢迎回家。'}],lift:0};}
 function assigned(s,f){return s.people.filter(p=>p.floor===f.id);}
 function roomRate(s,f,at=Date.now()){if(f.readyAt>at||!f.enabled)return {income:0,expense:0,net:0};const ps=assigned(s,f),base=f.income/f.capacity,income=ps.reduce((a,p)=>a+base*(p.specialty===ROOMS[f.type].category?1.25:1),0);return {income,expense:f.expense,net:income-f.expense};}
 function net(s,at=Date.now()){return s.floors.reduce((a,f)=>a+roomRate(s,f,at).net,0);}
 function beds(s,at=Date.now()){return s.floors.filter(f=>f.type==='dorm'&&f.readyAt<=at).reduce((n,f)=>n+f.capacity,0);}
 function log(s,text,at=Date.now()){s.logs.unshift({text,at});s.logs=s.logs.slice(0,15);}
 function settle(s,now=Date.now()){if(now<=s.lastTick)return {earned:0,offline:0};const elapsed=now-s.lastTick,from=Math.max(s.lastTick,now-MAX_OFFLINE),cuts=[from,...s.floors.filter(f=>f.readyAt>from&&f.readyAt<now).map(f=>f.readyAt),now].sort((a,b)=>a-b);let gain=0;for(let i=0;i<cuts.length-1;i++){const delta=net(s,cuts[i])*(cuts[i+1]-cuts[i])/60000;gain+=delta;s.coins=Math.max(0,s.coins+delta);if(delta>0)s.earned+=delta;}s.lastTick=now;return {earned:gain,offline:elapsed};}
 function build(s,type,now=Date.now()){settle(s,now);if(!Object.hasOwn(ROOMS,type))return {ok:false,reason:'未知房间类型'};const t=ROOMS[type];if(s.floors.length>=MAX_FLOORS)return {ok:false,reason:'已达到 30 层上限'};if(s.coins<t.cost)return {ok:false,reason:'金币不足'};s.coins-=t.cost;const f=floor(type,s.floors.length,now,true);s.floors.push(f);log(s,`B${f.level} ${f.name}${t.seconds?'开始建造':'建成了'}。`,now);return {ok:true,floor:f};}
 function assign(s,id,floorId,now=Date.now()){settle(s,now);const p=s.people.find(p=>p.id===id);if(!p)return {ok:false,reason:'未找到居民'};if(floorId!==null){const f=s.floors.find(f=>f.id===floorId);if(!f||f.readyAt>now)return {ok:false,reason:'楼层尚未建成'};if(p.floor!==floorId&&assigned(s,f).length>=f.capacity)return {ok:false,reason:'楼层人数已满'};}p.floor=floorId;s.visits=(s.visits||[]).filter(v=>v.person.id!==id);return {ok:true};}
 function toggle(s,id,now=Date.now()){settle(s,now);const f=s.floors.find(f=>f.id===id);if(!f||f.readyAt>now)return false;f.enabled=!f.enabled;return true;}
 function arrival(s,now=Date.now()){if(now<s.nextVisitorAt)return false;let changed=false;if(s.visitors.length<4){const targets=s.floors.filter(f=>f.readyAt<=now);if(targets.length){s.visitors.push({...person(s.nextId++),destination:targets[randint(targets.length)].id});changed=true;}}s.nextVisitorAt=now+45000;return changed;}
 function pruneVisits(s,now=Date.now()){const old=s.visits||[];s.visits=old.filter(v=>v.expiresAt>now&&!s.people.some(p=>p.id===v.person.id&&p.floor!==null));return old.length!==s.visits.length;}
 function present(s,f,now=Date.now()){const workers=assigned(s,f),visits=(s.visits||[]).filter(v=>v.floor===f.id&&v.expiresAt>now&&!s.people.some(p=>p.id===v.person.id&&p.floor!==null));const space=Math.max(0,f.capacity-workers.length);return {workers,guests:visits.slice(0,space),overflow:visits.slice(space)};}
 function deliver(s,id,destination,now=Date.now()){settle(s,now);const v=s.visitors.find(p=>p.id===id);if(!v||v.destination!==destination)return {ok:false,reason:'请送到访客指定的楼层'};const f=s.floors.find(f=>f.id===destination);if(!f||f.readyAt>now)return {ok:false,reason:'目标楼层尚未建成'};s.lift=destination;s.coins+=25;s.transported++;s.visitors=s.visitors.filter(p=>p.id!==id);const joined=s.people.length<beds(s,now),placed=joined&&assigned(s,f).length<f.capacity;if(joined){const p={...v,floor:placed?destination:null};delete p.destination;s.people.push(p);log(s,v.name+' 已入住社区。',now);}if(!placed){pruneVisits(s,now);s.visits.push({person:{...v,look:{...v.look}},floor:destination,expiresAt:now+60000});}return {ok:true,joined,placed,person:v};}
 function validate(s){const num=(v,min=0,max=1e14)=>Number.isFinite(v)&&v>=min&&v<=max,ids=new Set(),validLook=l=>l&&['head','top','bottom'].every(k=>Number.isInteger(l[k])&&l[k]>=0&&l[k]<16);if(!s||s.version!==VERSION||!num(s.coins)||!Array.isArray(s.floors)||s.floors.length<1||s.floors.length>30)return false;for(let i=0;i<s.floors.length;i++){const f=s.floors[i];if(!f||!Object.hasOwn(ROOMS,f.type)||f.id!==i+1||f.level!==i+1||typeof f.name!=='string'||f.name.length>40||!Number.isInteger(f.capacity)||f.capacity<2||f.capacity>5||!num(f.buildCost)||!num(f.buildSeconds,0,300)||!num(f.startedAt)||!num(f.readyAt)||f.readyAt<f.startedAt||!num(f.income,0,10000)||!num(f.expense,0,10000)||typeof f.enabled!=='boolean')return false;}
 const vp=p=>p&&Number.isInteger(p.id)&&p.id>0&&!ids.has(p.id)&&typeof p.name==='string'&&p.name.length>0&&p.name.length<=30&&Number.isInteger(p.age)&&p.age>=18&&p.age<=100&&Object.hasOwn(SPECIALTIES,p.specialty)&&validLook(p.look);
 if(!Array.isArray(s.people)||s.people.length>150||!Array.isArray(s.visitors)||s.visitors.length>4)return false;for(const p of s.people){if(!vp(p)||!(p.floor===null||s.floors.some(f=>f.id===p.floor)))return false;ids.add(p.id);}for(const v of s.visitors){if(!vp(v)||!s.floors.some(f=>f.id===v.destination))return false;ids.add(v.id);}for(const f of s.floors)if(assigned(s,f).length>f.capacity)return false;if(!['nextId','nextVisitorAt','createdAt','lastTick','earned','transported','lift'].every(k=>num(s[k]))||s.nextId<=Math.max(0,...ids)||!Number.isInteger(s.lift)||s.lift>s.floors.length)return false;if(!Array.isArray(s.claimed)||s.claimed.some(x=>typeof x!=='string')||!Array.isArray(s.logs)||s.logs.length>15||s.logs.some(x=>typeof x.text!=='string'||x.text.length>300||!num(x.at)))return false;if(s.visits!==undefined&&(!Array.isArray(s.visits)||s.visits.length>100||s.visits.some(v=>!v.person||!Number.isInteger(v.person.id)||typeof v.person.name!=='string'||v.person.name.length>30||!validLook(v.person.look)||!s.floors.some(f=>f.id===v.floor)||!num(v.expiresAt))))return false;return true;}
 function migrate(old,now=Date.now()){const s=fresh(now),map={home:'dorm',food:'cultivation',water:'supplies',work:'supplies',power:'energy',lounge:'boardgames'};if(!old||old.version!==1||!Array.isArray(old.rooms))return null;s.floors=old.rooms.slice(0,30).map((r,i)=>floor(map[r.type]||'dorm',i,now));s.coins=Number.isFinite(old.coins)&&old.coins>=0?old.coins:1000;s.people=(old.people||[]).slice(0,150).map((p,i)=>{const n=person(i+1);n.name=typeof p.name==='string'?p.name.slice(0,30):n.name;const f=s.floors[p.room];n.floor=f?f.id:null;n.specialty=f?ROOMS[f.type].category:n.specialty;return n;});for(const f of s.floors){for(const p of assigned(s,f).slice(f.capacity))p.floor=null;}if(!s.people.length)s.people=fresh(now).people;s.nextId=s.people.length+1;s.visitors=[{...person(s.nextId++),destination:Math.min(2,s.floors.length)}];log(s,'已保留旧版金币、楼层和居民，升级为新的社区经营规则。',now);return s;}
 return {fresh,person,build,assign,toggle,arrival,deliver,settle,roomRate,net,beds,assigned,log,validate,migrate,present,pruneVisits,MAX_OFFLINE};
})();
